import{_ as a,o as t,c as o,a3 as r}from"./chunks/framework.CWpttWmj.js";const u=JSON.parse('{"title":"Safety & cautions","description":"","frontmatter":{},"headers":[],"relativePath":"safety.md","filePath":"safety.md","lastUpdated":1785888355000}'),n={name:"safety.md"};function s(i,e,l,c,h,d){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="safety-cautions" tabindex="-1">Safety &amp; cautions <a class="header-anchor" href="#safety-cautions" aria-label="Permalink to &quot;Safety &amp; cautions&quot;">​</a></h1><p>Read this before you sign anything. Arc Names is a protocol with no support desk, no recovery mechanism and no reversals — the safeguards that exist are the ones you apply yourself.</p><h2 id="testnet-reality-check" tabindex="-1">Testnet reality check <a class="header-anchor" href="#testnet-reality-check" aria-label="Permalink to &quot;Testnet reality check&quot;">​</a></h2><p>Arc Names currently runs on <strong>Arc Testnet</strong>.</p><ul><li>Testnet tokens have <strong>no monetary value</strong>. Nobody should ever ask you to buy them, and any offer to sell them is a scam.</li><li>The deployment may be <strong>reset or redeployed</strong>. Names registered now carry no guarantee of surviving.</li><li>A testnet name grants <strong>no claim on a mainnet name</strong>. If anyone tells you registering now reserves a mainnet name, they are making that up.</li></ul><p>Use this to try the protocol, not to store anything you&#39;d miss.</p><h2 id="there-is-no-recovery" tabindex="-1">There is no recovery <a class="header-anchor" href="#there-is-no-recovery" aria-label="Permalink to &quot;There is no recovery&quot;">​</a></h2><p>The wallet holding the name <em>is</em> the name. If you lose access to it, the name is gone.</p><ul><li>No password reset. No support ticket. No admin who can move it back.</li><li>No way to reverse a transfer to a wrong address.</li><li>No way to recover from a phishing signature you approved.</li></ul><p>The protocol has no concept of your identity apart from your keys. This is the trade-off for nobody being able to take your name away either.</p><h2 id="protecting-a-name-you-care-about" tabindex="-1">Protecting a name you care about <a class="header-anchor" href="#protecting-a-name-you-care-about" aria-label="Permalink to &quot;Protecting a name you care about&quot;">​</a></h2><p><strong>Hold it in a wallet with real key security.</strong> A hardware wallet or a multisig. A hot browser wallet is fine for experimenting and a poor place for anything valuable.</p><p><strong>Back up the seed phrase offline.</strong> On paper or metal, never in a photo, cloud note, password manager sync, or anywhere connected to a network. Nobody legitimate will ever ask for it — not Arc Names, not a moderator, not &quot;support&quot;. Anyone who does is stealing from you.</p><p><strong>Renew from a different wallet.</strong> Renewal is permissionless — anyone can renew any name. So a name held in cold storage can be renewed from a hot wallet without ever exposing the hardware key. Use this. It means the wallet holding a valuable name almost never has to sign anything.</p><p><strong>Register for longer.</strong> Fewer renewals means fewer chances to forget, and fewer transactions.</p><h2 id="look-alike-names" tabindex="-1">Look-alike names <a class="header-anchor" href="#look-alike-names" aria-label="Permalink to &quot;Look-alike names&quot;">​</a></h2><p>The on-chain validity check is looser than the app&#39;s. <code>ArcController.valid()</code> enforces length and rejects uppercase ASCII — and nothing else. It does not restrict the character set.</p><p>The app only lets you <em>type</em> lowercase letters, digits and hyphens. But anyone calling the contract directly can register a name containing Unicode, invisible characters, or glyphs that render identically to ASCII.</p><div class="danger custom-block"><p class="custom-block-title">A name that looks right may not be the name you think</p><p>Two names can be visually indistinguishable and be entirely different on-chain. This is the classic homoglyph attack, and a naming service is exactly where it&#39;s most valuable to an attacker.</p><p>Never judge a name by its appearance in a marketplace listing, an activity feed, a DM, or a screenshot. Before acting on one:</p><ul><li>Resolve it and check the <strong>address</strong> it points at.</li><li>Compare that against an address you obtained independently.</li><li>For anything consequential, copy the name and inspect it — a name with unexpected characters will not match the one you expect byte for byte.</li></ul></div><h2 id="reverse-records-are-claims-not-proof" tabindex="-1">Reverse records are claims, not proof <a class="header-anchor" href="#reverse-records-are-claims-not-proof" aria-label="Permalink to &quot;Reverse records are claims, not proof&quot;">​</a></h2><p>Anyone can set their reverse record to any string. <code>attacker.arc</code> can claim to be <code>vitalik.arc</code>.</p><p>The only thing that makes a reverse name trustworthy is the <strong>round-trip</strong>: the name must forward- resolve back to the same address. The UniversalResolver returns a <code>verified</code> flag that does this check.</p><p>If you are building an interface: <strong>never display an unverified reverse name.</strong> Fall back to the raw address. Displaying an unverified name is how your users get phished. See <a href="/docs/guide/primary-name.html#verification-and-why-it-matters">Your primary name</a>.</p><h2 id="buying-a-name-safely" tabindex="-1">Buying a name safely <a class="header-anchor" href="#buying-a-name-safely" aria-label="Permalink to &quot;Buying a name safely&quot;">​</a></h2><p><strong>Only pay inside an atomic transaction.</strong> The marketplace transfers the name and pays the seller in the same transaction — either both happen or neither does.</p><div class="danger custom-block"><p class="custom-block-title">&quot;Send me the money and I&#39;ll transfer it&quot; is theft</p><p>There is no escrow, no dispute process, no reversal. If you send funds first, you have no recourse. This is the most common way people lose money in naming services.</p><p>Use a marketplace listing, or a contract that swaps both sides atomically. Never a handshake.</p></div><p><strong>Always pass an explicit <code>maxPrice</code>.</strong> The <code>buy(id)</code> overload sets the maximum to whatever you sent, so a seller can front-run your purchase with a price increase and take it. Use <code>buy(id, maxPrice)</code>.</p><p><strong>Check the expiry before you buy.</strong> A name with two weeks left needs renewing immediately, and that cost is part of the real price.</p><p><strong>After buying, reclaim and update <code>setAddr</code>.</strong> Until you do, the seller may still control your records, and the name still resolves to <em>their</em> address — so anyone paying it pays them.</p><h2 id="approvals" tabindex="-1">Approvals <a class="header-anchor" href="#approvals" aria-label="Permalink to &quot;Approvals&quot;">​</a></h2><p><code>setApprovalForAll</code> authorises an operator over <strong>every name you hold and every name you register in future</strong>, until you revoke it.</p><ul><li>Prefer per-token <code>approve</code> where possible.</li><li>Only grant blanket approval to contracts you have a reason to trust.</li><li>Revoke when you&#39;re done. Approvals do not expire.</li></ul><p>A malicious contract with blanket approval can take every name you own in one transaction.</p><h2 id="verifying-contract-addresses" tabindex="-1">Verifying contract addresses <a class="header-anchor" href="#verifying-contract-addresses" aria-label="Permalink to &quot;Verifying contract addresses&quot;">​</a></h2><p>Fake addresses that mimic the real contracts are the most common phishing vector in any naming service.</p><ul><li>Get addresses from <a href="/docs/protocol/contracts.html">Contract addresses</a>, served from a site you navigated to yourself.</li><li>Cross-check on <a href="https://testnet.arcscan.app" target="_blank" rel="noreferrer">testnet.arcscan.app</a> — confirm it&#39;s a contract with plausible history.</li><li>Confirm you&#39;re on chain ID <code>5042002</code>.</li><li><strong>Never take a contract address from a DM</strong>, a support chat, or a search advert.</li></ul><p>Remember also that every address is a <strong>proxy</strong>. Calling an implementation directly returns zeros rather than reverting — a silent failure that looks like &quot;the name doesn&#39;t exist&quot;.</p><h2 id="reading-what-you-sign" tabindex="-1">Reading what you sign <a class="header-anchor" href="#reading-what-you-sign" aria-label="Permalink to &quot;Reading what you sign&quot;">​</a></h2><p>Before confirming any transaction, check three things in your wallet:</p><ol><li><strong>The contract</strong> you&#39;re calling — does it match an address from the official docs?</li><li><strong>The function</strong> — does it match what you think you&#39;re doing? <code>setApprovalForAll</code> when you expected <code>list</code> is an attack.</li><li><strong>The value</strong> — is the amount what you expected?</li></ol><p>A transaction that asks for far more than the price you were shown, or for approval you didn&#39;t request, should be rejected.</p><h2 id="records-are-public-and-permanent" tabindex="-1">Records are public and permanent <a class="header-anchor" href="#records-are-public-and-permanent" aria-label="Permalink to &quot;Records are public and permanent&quot;">​</a></h2><p>Everything in a text record is plaintext on a public chain, readable by anyone, forever. Overwriting does not erase — the old value stays in transaction history.</p><p>Don&#39;t put anything in a record you wouldn&#39;t publish. An <code>email</code> record will be scraped.</p><p>Nothing in a record is verified. A <code>com.twitter</code> record is a self-reported claim; the protocol never checks it.</p><h2 id="trust-assumptions" tabindex="-1">Trust assumptions <a class="header-anchor" href="#trust-assumptions" aria-label="Permalink to &quot;Trust assumptions&quot;">​</a></h2><p>Being honest about what you&#39;re trusting:</p><p><strong>The contract owner can upgrade every contract.</strong> All are UUPS proxies. An upgrade can change any behaviour described in these docs. This allows fixing bugs; it also means the rules can change.</p><p><strong>The owner controls prices, <code>minLen</code>, commit ages, fees and referral rates.</strong> Not <code>GRACE</code>, <code>MIN_DURATION</code> or <code>MAX_DURATION</code> — those are hard constants.</p><p><strong>The indexer can be wrong.</strong> It lags the chain and can fail. For display that&#39;s fine; for anything that moves value, read the contracts. Check <code>/api/v1/sync-status</code>.</p><p><strong>These contracts have not been through a published third-party audit.</strong> Treat the deployment accordingly.</p><h2 id="when-the-app-can-t-reach-the-network" tabindex="-1">When the app can&#39;t reach the network <a class="header-anchor" href="#when-the-app-can-t-reach-the-network" aria-label="Permalink to &quot;When the app can&#39;t reach the network&quot;">​</a></h2><p>If you see <em>&quot;Can&#39;t reach the Arc network right now&quot;</em>, the app cannot talk to its RPC endpoint.</p><p>The usual cause is CORS. The public endpoint <code>https://rpc.testnet.arc.network</code> does not send CORS headers, so it fails from every browser tab while working perfectly from <code>curl</code> or a server. A browser deployment needs a provider endpoint that sets CORS headers. See <a href="/docs/guide/connecting-a-wallet.html#rpc-endpoints">Connecting a wallet</a>.</p><p>Browsers cannot distinguish a CORS block from DNS failure or a server being down — all three surface identically as an opaque fetch rejection. So this message means &quot;the request didn&#39;t complete&quot;, not necessarily &quot;the network is down&quot;.</p><p><strong>This is not a reason to enter your seed phrase anywhere.</strong> No network problem is ever fixed by providing a seed phrase.</p><h2 id="deploying-the-app-yourself" tabindex="-1">Deploying the app yourself <a class="header-anchor" href="#deploying-the-app-yourself" aria-label="Permalink to &quot;Deploying the app yourself&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">Any VITE_ variable is public</p><p>Vite compiles <code>VITE_*</code> variables into the JavaScript bundle it ships to browsers. Anyone loading your app can extract them. This is unavoidable for a client-side app.</p><ul><li>Set a <strong>domain allowlist</strong> on any RPC provider key so it only works from your origin.</li><li>Never put a key with billing or write authority in a <code>VITE_</code> variable.</li><li>Rotate any key that has been pasted into a chat, a ticket, or a commit.</li></ul></div><h2 id="scams-to-expect" tabindex="-1">Scams to expect <a class="header-anchor" href="#scams-to-expect" aria-label="Permalink to &quot;Scams to expect&quot;">​</a></h2><ul><li><strong>&quot;Claim your mainnet name now.&quot;</strong> There is no mainnet claim.</li><li><strong>&quot;Verify your wallet to keep your name.&quot;</strong> Never a real requirement.</li><li><strong>&quot;Support&quot; asking for your seed phrase.</strong> Always theft.</li><li><strong>Look-alike names</strong> in listings or DMs. See <a href="#look-alike-names">above</a>.</li><li><strong>A cheap listing for a valuable name.</strong> Check the expiry and the exact characters.</li><li><strong>Fake app URLs.</strong> Bookmark the real one and use the bookmark.</li><li><strong>Airdrop or points claims</strong> requiring approval of an unknown contract.</li></ul><h2 id="if-something-goes-wrong" tabindex="-1">If something goes wrong <a class="header-anchor" href="#if-something-goes-wrong" aria-label="Permalink to &quot;If something goes wrong&quot;">​</a></h2><p><strong>Approved a malicious transaction:</strong> immediately revoke approvals from the affected wallet and move remaining assets to a wallet whose keys have never touched that machine.</p><p><strong>Sent a name to a wrong address:</strong> it is not recoverable. If the address belongs to someone reachable, ask.</p><p><strong>Let a name expire:</strong> you have 90 days from the expiry to renew it. Do it now — see <a href="/docs/guide/renewals.html">Renewals &amp; expiry</a>.</p><p><strong>Lost your commit secret mid-registration:</strong> you lose the commit gas only. Start again.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/docs/guide/connecting-a-wallet.html">Connecting a wallet</a> — network setup.</li><li><a href="/docs/protocol/contracts.html">Contract addresses</a> — verified addresses.</li><li><a href="/docs/reference/faq.html">FAQ</a> — common questions and errors.</li></ul>',67)])])}const m=a(n,[["render",s]]);export{u as __pageData,m as default};
